39	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
40	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
41	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
42	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
43	        List<String> missing = new ArrayList<>();
44	        require(missing, "firstName", request.getFirstName());
45	        require(missing, "lastName", request.getLastName());
46	        require(missing, "address", request.getAddress());
47	        require(missing, "city", request.getCity());
48	        require(missing, "telephone", request.getTelephone());
49	        if (!missing.isEmpty()) {
50	            throw new MissingOwnerFieldsException(missing);
51	        }
52	
53	        // Normalize the telephone: keep only digits, then require exactly ten. Store the stripped
54	        // value back so BuildOwner/SaveOwner persist it and the response echoes the 10-digit form.
55	        String normalized = OwnerTelephone.normalize(request.getTelephone());
56	        if (normalized.length() != 10) {
57	            throw new InvalidTelephoneException(normalized);
58	        }
59	        request.setTelephone(normalized);
60	
61	        // Email is optional: only an email that is present (non-blank) must be a valid address. A valid
62	        // value is lower-cased and written back (like telephone above) so downstream steps store and
63	        // return the canonical form.
64	        String email = request.getEmail();
65	        if (email != null && !email.isBlank()) {
66	            if (!EMAIL_PATTERN.matcher(email).matches()) {
67	                throw new InvalidEmailException(email);
68	            }
69	            request.setEmail(email.toLowerCase());
70	        }
