package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

/**
 * Responds 400 with an RFC-7807 {@link ProblemDetail} (built through the shared {@link ProblemDetails}
 * helper, like every other handler in this package) when a new owner's telephone is not exactly ten
 * digits once non-digit characters are stripped.
 */
public class InvalidTelephoneExceptionHandler {

    public void handle(@Parameter InvalidTelephoneException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
                "The telephone must be exactly 10 digits after removing non-digit characters");
        detail.setProperty("errors", java.util.List.of("telephone"));
        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
    }
}

package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a request to create an owner carries a normalized telephone that already belongs to
 * another owner. Carries the offending (digits-only) telephone so
 * {@link DuplicateTelephoneExceptionHandler} can report it. Checked so it appears in the function's
 * {@code throws} clause and is routed as an escalation (a 409 Conflict).
 */
public class DuplicateTelephoneException extends Exception {

    private final String telephone;

    public DuplicateTelephoneException(String telephone) {
        super("An owner with telephone '" + telephone + "' already exists");
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}

